    55	 * What the office carries for an item. The MHPCO has not yet published an insurance
    56	 * value for every type it prices, so this column can be absent -- unlike the premium
    57	 * column, this lookup does not yet reject an unlisted type. Both gaps are still
    58	 * driven by inactive tests.
    59	 */
    60	export function insuranceValueOf(item: Item): number | undefined {
