     1	import { type Item, basePremiumOf, isComponent } from "./price-list.js";
     2	import { amountOwedToMHPCO } from "./rounding.js";
     3	
     4	export interface Customer {
     5	  yearsWithMHPCO: number;
     6	}
     7	
     8	const PROCESSING_FEE = 5;
     9	const CURSE_SURCHARGE_RATE = 0.5;
    10	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
    11	const HIGH_ENCHANTMENT_THRESHOLD = 5;
    12	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
    13	const LOYALTY_DISCOUNT_RATE = 0.2;
    14	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
    15	const LOYALTY_YEARS_THRESHOLD = 2;
    16	
    17	const BLOCK_SIZE = 3;
    18	const BLOCK_BASE_PREMIUM = 60;
    19	
    20	/** "Alike" resolved as exactly the same component type, not the same family. */
    21	function alikenessOf(component: Item): string {
    22	  return component.type;
    23	}
    24	
    25	/** The alike components of one alikeness, which are priced together. */
    26	interface AlikeGroup {
    27	  member: Item;
    28	  count: number;
    29	}
    30	
    31	function groupAlike(components: Item[]): AlikeGroup[] {
    32	  const groups = new Map<string, AlikeGroup>();
    33	  for (const component of components) {
    34	    const alikeness = alikenessOf(component);
    35	    const group = groups.get(alikeness);
    36	    if (group === undefined) {
    37	      groups.set(alikeness, { member: component, count: 1 });
    38	    } else {
    39	      group.count += 1;
    40	    }
    41	  }
    42	  return [...groups.values()];
    43	}
    44	
    45	/** A block is exactly 3 alike components -- 4 alike do not form a block. */
    46	function formsBlock(alikeCount: number): boolean {
    47	  return alikeCount === BLOCK_SIZE;
    48	}
    49	
    50	function alikeGroupBasePremiumOf(group: AlikeGroup): number {
    51	  return formsBlock(group.count) ? BLOCK_BASE_PREMIUM : group.count * basePremiumOf(group.member);
    52	}
    53	
    54	function componentsBasePremiumOf(components: Item[]): number {
    55	  return groupAlike(components).reduce((total, group) => total + alikeGroupBasePremiumOf(group), 0);
    56	}
    57	
    58	function mainItemsBasePremiumOf(mainItems: Item[]): number {
    59	  return mainItems.reduce((total, item) => total + basePremiumOf(item), 0);
    60	}
    61	
    62	function isCursed(item: Item): boolean {
    63	  return item.cursed === true;
    64	}
    65	
    66	function isHighlyEnchanted(item: Item): boolean {
    67	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
    68	}
    69	
    70	interface RiskSurcharge {
    71	  appliesTo: (item: Item) => boolean;
    72	  rate: number;
    73	}
    74	
    75	const ITEM_RISK_SURCHARGES: RiskSurcharge[] = [
    76	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
    77	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
    78	];
    79	
    80	function itemRiskSurchargeOf(item: Item): number {
    81	  const applicableRate = ITEM_RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
    82	    (total, surcharge) => total + surcharge.rate,
    83	    0,
    84	  );
    85	  return basePremiumOf(item) * applicableRate;
    86	}
    87	
    88	function itemSurchargesOf(items: Item[]): number {
    89	  return items.reduce((total, item) => total + itemRiskSurchargeOf(item), 0);
    90	}
    91	
    92	function policyBasePremiumOf(items: Item[]): number {
    93	  const mainItems = items.filter((item) => !isComponent(item));
    94	  const components = items.filter(isComponent);
    95	  return mainItemsBasePremiumOf(mainItems) + componentsBasePremiumOf(components);
    96	}
    97	
    98	/** What MHPCO knows about the customer at the moment this quote is written. */
    99	interface CustomerHistory {
   100	  customer: Customer;
   101	  previousContracts: number;
   102	}
   103	
   104	function isLongStanding(history: CustomerHistory): boolean {
   105	  return history.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
   106	}
   107	
   108	function isFollowUpContract(history: CustomerHistory): boolean {
   109	  return history.previousContracts > 0;
   110	}
   111	
   112	function loyaltyDiscountOf(history: CustomerHistory, policyBasePremium: number): number {
   113	  return isLongStanding(history) ? policyBasePremium * LOYALTY_DISCOUNT_RATE : 0;
   114	}
   115	
   116	/** Every quoted item is a first insurance, regardless of the customer's history. */
   117	function firstInsuranceSurchargeOf(policyBasePremium: number): number {
   118	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
   119	}
   120	
   121	function followUpDiscountOf(history: CustomerHistory, policyBasePremium: number): number {
   122	  return isFollowUpContract(history) ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
   123	}
   124	
   125	function policyModifiersOf(history: CustomerHistory, policyBasePremium: number): number {
   126	  return (
   127	    firstInsuranceSurchargeOf(policyBasePremium) -
   128	    loyaltyDiscountOf(history, policyBasePremium) -
   129	    followUpDiscountOf(history, policyBasePremium)
   130	  );
   131	}
   132	
   133	export function quote(customer: Customer, items: Item[], previousContracts = 0): number {
   134	  const history: CustomerHistory = { customer, previousContracts };
   135	  const policyBasePremium = policyBasePremiumOf(items);
   136	  return amountOwedToMHPCO(
   137	    policyBasePremium +
   138	    itemSurchargesOf(items) +
   139	    policyModifiersOf(history, policyBasePremium) +
   140	    PROCESSING_FEE,
   141	  );
   142	}
