     1	import { type Item } from "./price-list.js";
     2	import { amountOwedByMHPCO } from "./rounding.js";
     3	
     4	/** What one damaged item lost in an incident, as the claim report states it. */
     5	export interface Damage {
     6	  itemType: string;
     7	  amount: number;
     8	}
     9	
    10	const DEDUCTIBLE_PER_DAMAGE = 100;
    11	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
    12	const HIGH_ENCHANTMENT_REIMBURSED_SHARE = 0.5;
    13	const FULL_REIMBURSEMENT = 1;
    14	
    15	/**
    16	 * The claim clause's own enchantment test. The quote side has a high-enchantment
    17	 * rule too, at a different threshold and for a different effect; the two are
    18	 * separate entries in the MHPCO clause book and move independently.
    19	 */
    20	function qualifiesForHighEnchantmentClause(item: Item): boolean {
    21	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
    22	}
    23	
    24	/**
    25	 * The share of a damage the office carries before the deductible is charged.
    26	 *
    27	 * The MHPCO clause book grants full reimbursement as its standing position: an item
    28	 * the office insures is made whole unless a clause cuts that share. The dragon-material
    29	 * clause of the rules grants exactly that standing share, so it discriminates nothing
    30	 * and is not a branch here; the spec confirms this by settling a steel sword with no
    31	 * clause at all on the same full share. The high-enchantment clause is the one clause
    32	 * that cuts, and it takes precedence over full reimbursement wherever both would speak
    33	 * -- a dragon sword at enchantment 9 is settled at 50 %, not at 100 %.
    34	 */
    35	function reimbursedShareOf(item: Item): number {
    36	  return qualifiesForHighEnchantmentClause(item)
    37	    ? HIGH_ENCHANTMENT_REIMBURSED_SHARE
    38	    : FULL_REIMBURSEMENT;
    39	}
    40	
    41	/**
    42	 * The loss a damage entry states. The office settles losses, so a figure below zero
    43	 * is not a damage it can read -- the report is refused rather than paid out in
    44	 * reverse. This tests the report as written, before any clause is consulted.
    45	 */
    46	function reportedAmountOf(damage: Damage): number {
    47	  if (damage.amount < 0) {
    48	    throw new Error(`A damage amount cannot be negative, but the claim reports ${damage.amount}.`);
    49	  }
    50	  return damage.amount;
    51	}
    52	
    53	/**
    54	 * What the office owes for one damaged item: the share its clauses carry, less the
    55	 * deductible charged per damage event -- an incident that harms two items is
    56	 * reduced twice, so the payout is assembled per damaged item rather than per
    57	 * incident.
    58	 */
    59	function reimbursementFor(damage: Damage, damagedItem: Item): number {
    60	  return reportedAmountOf(damage) * reimbursedShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
    61	}
    62	
    63	/**
    64	 * The insured item a damage entry names, resolved against what the policy carries.
    65	 * The policy is the sole authority on what the office settles, so the lookup that
    66	 * finds the damaged item is also the one that refuses a type -- unknown to the price
    67	 * list or simply not on this policy -- that the policy does not cover.
    68	 *
    69	 * Each insured item answers at most one damage, so the matched item is taken out of
    70	 * the items still unclaimed: a policy carrying one sword cannot answer two sword
    71	 * damages.
    72	 */
    73	function claimInsuredItemFor(unclaimedItems: Item[], damage: Damage): Item {
    74	  const index = unclaimedItems.findIndex((item) => item.type === damage.itemType);
    75	  if (index === -1) {
    76	    throw new Error(`The policy does not cover an item of type "${damage.itemType}".`);
    77	  }
    78	  return unclaimedItems.splice(index, 1)[0];
    79	}
    80	
    81	/** A damage entry and the insured item the policy assigns to it. */
    82	interface ClaimedDamage {
    83	  damage: Damage;
    84	  damagedItem: Item;
    85	}
    86	
    87	/**
    88	 * How the policy answers an incident: each reported damage is assigned the insured
    89	 * item that settles it, and no item settles twice. Assignment is the office's own
    90	 * decision -- which item answers which damage, and when the report asks for more
    91	 * than the policy carries -- and is made in full before any money is counted.
    92	 */
    93	function claimedDamagesOf(items: Item[], damages: Damage[]): ClaimedDamage[] {
    94	  const unclaimedItems = [...items];
    95	  return damages.map((damage) => ({
    96	    damage,
    97	    damagedItem: claimInsuredItemFor(unclaimedItems, damage),
    98	  }));
    99	}
   100	
   101	export function payoutFor(items: Item[], damages: Damage[]): number {
   102	  const reimbursed = claimedDamagesOf(items, damages).reduce(
   103	    (payout, claimed) => payout + reimbursementFor(claimed.damage, claimed.damagedItem),
   104	    0,
   105	  );
   106	  return amountOwedByMHPCO(reimbursed);
   107	}
   108	
   109	/** What the office pays for one incident, and what the policy's cap has left afterwards. */
   110	export interface Settlement {
   111	  payout: number;
   112	  remainingCap: number;
   113	}
   114	
   115	/**
   116	 * The office never pays out more than the policy's cap still allows: a desired
   117	 * payout beyond the remaining cap is reduced to it, and the cap falls by what is
   118	 * actually paid. The payout arriving here is already rounded in the office's
   119	 * favour, and the remaining cap is integral, so the cap reduction cannot
   120	 * reintroduce a fraction.
   121	 */
   122	export function settleClaim(items: Item[], damages: Damage[], capRemaining: number): Settlement {
   123	  const payout = Math.min(payoutFor(items, damages), capRemaining);
   124	  return { payout, remainingCap: capRemaining - payout };
   125	}
