     1	/**
     2	 * Rounding in the MHPCO's favour: a single editorial rule of the office, stated
     3	 * once and applied in both directions of money flow. Whichever way an amount
     4	 * travels, the office keeps the fraction -- so what the customer owes rises to
     5	 * the whole G and what the office owes falls to it. The two functions below are
     6	 * the two directions of that one rule, which is why they are carried together:
     7	 * should the office ever restate what "in our favour" means, it restates both
     8	 * in one act.
     9	 *
    10	 * Only a final premium or payout is rounded; intermediate amounts stay fractions.
    11	 */
    12	
    13	/** What the customer owes the office. The office keeps the fraction, so it rises. */
    14	export function amountOwedToMHPCO(amount: number): number {
    15	  return Math.ceil(amount);
    16	}
    17	
    18	/** What the office owes the customer. The office keeps the fraction, so it falls. */
    19	export function amountOwedByMHPCO(amount: number): number {
    20	  return Math.floor(amount);
    21	}
