     6	export interface QuoteStep {
     7	  op: "quote";
     8	  items: Item[];
     9	}
    10	
    11	export interface Incident {
    12	  cause: string;
    13	  damages: Damage[];
    14	}
    15	
    16	/** A claim names the policy it is settled against by the index of the step that wrote it. */
    17	export interface ClaimStep {
    18	  op: "claim";
    19	  policy: number;
    20	  incident: Incident;
    21	}
    22	
    23	export type Step = QuoteStep | ClaimStep;
    24	
    25	export interface Scenario {
    26	  customer: Customer;
    27	  steps: Step[];
    28	}
    29	
    30	export interface QuoteResult {
    31	  premium: number;
    32	}
    33	
    34	export interface ClaimResult {
    35	  payout: number;
    36	  remainingCap: number;
    37	}
    38	
    39	export interface ScenarioResults {
    40	  results: (QuoteResult | ClaimResult)[];
    41	}
    42	
    43	/** The office never pays a policy more than twice what it carries for its items. */
    44	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    45	
    46	interface WrittenPolicy {
    47	  items: Item[];
    48	  capRemaining: number;
    49	}
    50	
    51	function writePolicy(items: Item[]): WrittenPolicy {
    52	  return { items, capRemaining: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM };
    53	}
    54	
    55	function policyClaimedBy(policies: Map<number, WrittenPolicy>, step: ClaimStep): WrittenPolicy {
    56	  const policy = policies.get(step.policy);
    57	  if (policy === undefined) {
    58	    throw new Error(`Step ${step.policy} did not write a policy to claim against.`);
    59	  }
    60	  return policy;
    61	}
    62	
    63	/**
    64	 * The office works a customer's steps in the order they were filed: each quote
    65	 * writes a policy the later steps can claim against, and each is a follow-up
    66	 * contract to the quotes already written for that customer.
    67	 */
    68	export function runScenario(scenario: Scenario): ScenarioResults {
    69	  const policies = new Map<number, WrittenPolicy>();
    70	  const results = scenario.steps.map((step, stepIndex) => {
    71	    if (step.op === "quote") {
    72	      const premium = quote(scenario.customer, step.items, policies.size);
    73	      policies.set(stepIndex, writePolicy(step.items));
    74	      return { premium };
    75	    }
    76	    const policy = policyClaimedBy(policies, step);
    77	    const settlement = settleClaim(policy.items, step.incident.damages, policy.capRemaining);
    78	    policy.capRemaining = settlement.remainingCap;
    79	    return settlement;
    80	  });
    81	  return { results };
    82	}
